wb = openpyxl.load_workbook(SRC, data_only=True)
ws = wb["Замечания"]
rows = {i: r for i, r in enumerate(ws.iter_rows(values_only=True), 1)}
s = lambda v: "" if v is None else str(v).strip()

out = openpyxl.Workbook()
o = out.active; o.title = "В109"
hdr = ["Группа", "Строка в исх. файле", "№", "Дата", "Раздел", "Документ", "Автор", "Статус", "Содержание замечания (полностью)", "Ответственный", "Что сделать", "Примечание / дубли", "Ответ (заполнить)"]
o.append(hdr)
for row, grp, who, todo, note in A:
    if row:
        r = rows[row]
        o.append([grp, row, s(r[0]), s(r[1])[:10], s(r[3]), s(r[5]), s(r[10]), s(r[11]), s(r[8]), who, todo, note, ""])
    else:
        o.append([grp, "—", "", "", "", "", "", "", "", who, todo, note, ""])

thin = Side(style="thin", color="999999")
fills = {}
pal = ["FCE4D6", "FFF2CC", "E2EFDA", "DDEBF7", "EDE7F6", "E0F7FA", "F8E1EC", "EEEEEE", "FFF8E1", "E8F5E9", "F3E5F5"]
widths = [16, 9, 6, 11, 22, 26, 20, 10, 70, 16, 70, 34, 30]
for i, w in enumerate(widths): o.column_dimensions[chr(65 + i)].width = w
for c in o[1]:
    c.font = Font(bold=True, color="FFFFFF"); c.fill = PatternFill("solid", fgColor="305496")
    c.alignment = Alignment(wrap_text=True, vertical="center", horizontal="center")
for row in o.iter_rows(min_row=2):
    g = row[0].value
    if g not in fills: fills[g] = PatternFill("solid", fgColor=pal[len(fills) % len(pal)])
    for c in row:
        c.alignment = Alignment(wrap_text=True, vertical="top"); c.border = Border(left=thin, right=thin, top=thin, bottom=thin)
    row[0].fill = fills[g]; row[10].fill = fills[g]
    if "(мы)" in str(row[9].value): row[9].font = Font(bold=True, color="C00000")
    if "ЗАКРЫТО" in str(row[11].value):
        for c in row: c.font = Font(color="808080")
o.freeze_panes = "C2"; o.auto_filter.ref = o.dimensions

# сводка
sv = out.create_sheet("Сводка")
sv.append(["Группа", "Кол-во", "Наше (КЖ/КМ)"])
from collections import Counter
cnt = Counter(g for _, g, *_ in A); ours = Counter(g for _, g, w, *_ in A if "(мы)" in w)
for g in sorted(cnt): sv.append([g, cnt[g], ours.get(g, 0)])
sv.append(["ИТОГО", sum(cnt.values()), sum(ours.values())])
sv.column_dimensions["A"].width = 26
out.save(DST)
print("saved", DST, len(A), dict(cnt), "ours", sum(ours.values()))
